R["cx-m6-count-distinct"] = "public class Solution {\n    // CONTRACT: count distinct values in arr (empty array -> 0).\n    public static int countDistinct(int[] arr) {\n        int distinct = 0;\n        for (int i = 0; i < arr.length; i++) {\n            boolean seen = false;\n            for (int j = 0; j < i; j++) {\n                if (arr[j] == arr[i]) { seen = true; break; }\n            }\n            if (!seen) { distinct++; }\n        }\n        return distinct;\n    }\n}\n";
W["cx-m6-count-distinct"] = "public class Solution {\n    // CONTRACT: count distinct values in arr (empty array -> 0).\n    public static int countDistinct(int[] arr) {\n        int distinct = 0;\n        for (int i = 0; i < arr.length; i++) {\n            boolean seen = false;\n            for (int j = 0; j <= i; j++) {\n                if (arr[j] == arr[i]) { seen = true; break; }\n            }\n            if (!seen) { distinct++; }\n        }\n        return distinct;\n    }\n}\n";
