R["cx-m8-max-column"] = "public class Solution {\n    // CONTRACT: index of the column with the LARGEST sum; ties -> the\n    // EARLIEST such column. Precondition: grid.length >= 1 and\n    // grid[0].length >= 1 (rectangular).\n    public static int maxColumn(int[][] grid) {\n        int bestCol = 0;\n        int bestSum = Integer.MIN_VALUE;\n        for (int c = 0; c < grid[0].length; c++) {\n            int sum = 0;\n            for (int r = 0; r < grid.length; r++) {\n                sum += grid[r][c];\n            }\n            if (sum > bestSum) {\n                bestSum = sum;\n                bestCol = c;\n            }\n        }\n        return bestCol;\n    }\n}\n";
W["cx-m8-max-column"] = "public class Solution {\n    // CONTRACT: index of the column with the LARGEST sum; ties -> the\n    // EARLIEST such column. Precondition: grid.length >= 1 and\n    // grid[0].length >= 1 (rectangular).\n    public static int maxColumn(int[][] grid) {\n        int bestCol = 0;\n        int bestSum = Integer.MIN_VALUE;\n        for (int c = 0; c < grid[0].length; c++) {\n            int sum = 0;\n            for (int r = 0; r < grid.length; r++) {\n                sum += grid[r][c];\n            }\n            if (sum >= bestSum) {\n                bestSum = sum;\n                bestCol = c;\n            }\n        }\n        return bestCol;\n    }\n}\n";
R["cx-m8-count-neighbors"] = "public class Solution {\n    // CONTRACT: count orthogonal neighbors of (row, col) that equal\n    // value. Edges and corners legitimately have fewer neighbors.\n    public static int countNeighbors(int[][] grid, int row, int col, int value) {\n        int count = 0;\n        if (row > 0 && grid[row - 1][col] == value) { count++; }\n        if (row < grid.length - 1 && grid[row + 1][col] == value) { count++; }\n        if (col > 0 && grid[row][col - 1] == value) { count++; }\n        if (col < grid[row].length - 1 && grid[row][col + 1] == value) { count++; }\n        return count;\n    }\n}\n";
W["cx-m8-count-neighbors"] = "public class Solution {\n    // CONTRACT: count orthogonal neighbors of (row, col) that equal\n    // value. Edges and corners legitimately have fewer neighbors.\n    public static int countNeighbors(int[][] grid, int row, int col, int value) {\n        int count = 0;\n        if (row >= 0 && grid[row - 1][col] == value) { count++; }\n        if (row < grid.length - 1 && grid[row + 1][col] == value) { count++; }\n        if (col > 0 && grid[row][col - 1] == value) { count++; }\n        if (col < grid[row].length - 1 && grid[row][col + 1] == value) { count++; }\n        return count;\n    }\n}\n";
