W["cx-m8-fix-row-swap"] = "public class Solution {\n    public static void swapRows(int[][] grid, int a, int b) {\n        int[] tmp = new int[grid[a].length];\n        for (int c = 0; c < grid[a].length; c++) {\n            tmp[c] = grid[a][c];\n        }\n        for (int c = 0; c < grid[a].length; c++) {\n            grid[a][c] = grid[b][c];\n        }\n        for (int c = 0; c < grid[a].length; c++) {\n            grid[b][c] = grid[a][c];\n        }\n    }\n}\n";
R["cx-cp-m8-path"] = "public class Solution {\n    public static int firstRepeat(int[][] grid, int row, int col) {\n        int rows = grid.length;\n        int cols = grid[0].length;\n        boolean[][] seen = new boolean[rows][cols];\n        int steps = 0;\n        int cap = rows * cols * 2;\n        while (steps <= cap) {\n            if (row < 0 || row >= rows || col < 0 || col >= cols) {\n                return -1;\n            }\n            if (seen[row][col]) {\n                return 10 * row + col;\n            }\n            seen[row][col] = true;\n            int code = grid[row][col];\n            row = code / 10;\n            col = code % 10;\n            steps++;\n        }\n        return -1;\n    }\n}\n";
W["cx-cp-m8-path"] = "public class Solution {\n    public static int firstRepeat(int[][] grid, int row, int col) {\n        int rows = grid.length;\n        int cols = grid[0].length;\n        boolean[][] seen = new boolean[rows][cols];\n        int steps = 0;\n        int cap = rows * cols * 2;\n        while (steps <= cap) {\n            if (row < 0 || row >= rows || col < 0 || col >= cols) {\n                return -1;\n            }\n            if (seen[row][col]) {\n                return 10 * col + row;\n            }\n            seen[row][col] = true;\n            int code = grid[row][col];\n            row = code % 10;\n            col = code / 10;\n            steps++;\n        }\n        return -1;\n    }\n}\n";
R["cx-m9-tollbooth"] = "public class Solution {\n    public static class TollBooth {\n        private int cars;\n        private int cash;\n\n        public TollBooth(int startingCash) {\n            cars = 0;\n            cash = startingCash;\n        }\n\n        // CONTRACT: one car pays 2. Returns the amount collected (2),\n        // or 0 if... cars never refuse to pay. Always collects.\n        public int carPasses() {\n            cars++;\n            cash += 2;\n            return 2;\n        }\n\n        public int getCars() { return cars; }\n        public int getCash() { return cash; }\n    }\n}\n";
