R["cx-m11-call-counter"] = "public class Solution {\n    // CONTRACT: f is already implemented. g(n) must return the TOTAL\n    // number of calls f makes when invoked as f(n), INCLUDING the\n    // initial call. f halves n: f(n) = 1 + f(n / 2) for n > 1,\n    // base n <= 1. So f(8) makes 4 calls: f(8), f(4), f(2), f(1).\n    public static int f(int n) {\n        if (n <= 1) { return 1; }\n        return 1 + f(n / 2);\n    }\n\n    public static int g(int n) {\n        int calls = 0;\n        while (n > 1) {\n            calls++;\n            n /= 2;\n        }\n        return calls + 1;\n    }\n}\n";
W["cx-m11-call-counter"] = "public class Solution {\n    // CONTRACT: f is already implemented. g(n) must return the TOTAL\n    // number of calls f makes when invoked as f(n), INCLUDING the\n    // initial call. f halves n: f(n) = 1 + f(n / 2) for n > 1,\n    // base n <= 1. So f(8) makes 4 calls: f(8), f(4), f(2), f(1).\n    public static int f(int n) {\n        if (n <= 1) { return 1; }\n        return 1 + f(n / 2);\n    }\n\n    public static int g(int n) {\n        int calls = 0;\n        while (n > 1) {\n            calls++;\n            n /= 2;\n        }\n        return calls;\n    }\n}\n";
R["cx-m11-subset-sum"] = "public class Solution {\n    // CONTRACT: can some subset of arr[i..] sum exactly to target?\n    // Empty subset sums to 0, so target 0 is always true.\n    public static boolean subset(int[] arr, int i, int target) {\n        if (target == 0) {\n            return true;\n        }\n        if (i >= arr.length) {\n            return false;\n        }\n        return subset(arr, i + 1, target - arr[i]) || subset(arr, i + 1, target);\n    }\n}\n";
W["cx-m11-subset-sum"] = "public class Solution {\n    // CONTRACT: can some subset of arr[i..] sum exactly to target?\n    // Empty subset sums to 0, so target 0 is always true.\n    public static boolean subset(int[] arr, int i, int target) {\n        if (i >= arr.length) {\n            return target == 0;\n        }\n        return subset(arr, i + 1, target - arr[i]) && subset(arr, i + 1, target);\n    }\n}\n";
R["cx-m12-distinct-positive"] = "public class Solution {\n    // CONTRACT (yours to diagnose): return the number of DISTINCT\n    // strictly-positive values in row 0 of grid. grid.length >= 1.\n    // {{3, -1, 3, 5}} -> 2 ; {{2, 2, 2}} -> 1 ; {{-4}} -> 0\n    public static int distinctPositive(int[][] grid) {\n        int[] row = grid[0];\n        int distinct = 0;\n        for (int i = 0; i < row.length; i++) {\n            if (row[i] > 0) {\n                boolean seen = false;\n                for (int j = 0; j < i; j++) {\n                    if (row[j] == row[i]) { seen = true; break; }\n                }\n                if (!seen) { distinct++; }\n            }\n        }\n        return distinct;\n    }\n}\n";
W["cx-m12-distinct-positive"] = "public class Solution {\n    // CONTRACT (yours to diagnose): return the number of DISTINCT\n    // strictly-positive values in row 0 of grid. grid.length >= 1.\n    // {{3, -1, 3, 5}} -> 2 ; {{2, 2, 2}} -> 1 ; {{-4}} -> 0\n    public static int distinctPositive(int[][] grid) {\n        int[] row = grid[0];\n        int distinct = 0;\n        for (int i = 0; i < row.length; i++) {\n            if (row[i] > 0) {\n                boolean seen = false;\n                for (int j = 0; j < i; j++) {\n                    if (row[j] == row[i]) { seen = true; break; }\n                }\n                if (!seen) { distinct += 2; }\n            }\n        }\n        return distinct;\n    }\n}\n";
