R["cx-m12-reproduce-process"] = "public class Solution {\n    // CONTRACT: from the lesson trace \u2014 reproduce process():\n    // pass 1: evens -> value / 2 (count them), odds -> value * 2 + 1\n    // pass 2: sum all; return sum - countOfEvens.\n    public static int process(int[] nums) {\n        int marked = 0;\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] % 2 == 0) {\n                nums[i] = nums[i] / 2;\n                marked++;\n            } else {\n                nums[i] = nums[i] * 2 + 1;\n            }\n        }\n        int total = 0;\n        for (int v : nums) {\n            total += v;\n        }\n        return total - marked;\n    }\n}\n";
W["cx-m12-reproduce-process"] = "public class Solution {\n    // CONTRACT: from the lesson trace \u2014 reproduce process():\n    // pass 1: evens -> value / 2 (count them), odds -> value * 2 + 1\n    // pass 2: sum all; return sum - countOfEvens.\n    public static int process(int[] nums) {\n        int marked = 0;\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] % 2 == 0) {\n                nums[i] = nums[i] / 2;\n                marked++;\n            } else {\n                nums[i] = nums[i] * 2 + 1;\n            }\n        }\n        int total = 0;\n        for (int v : nums) {\n            total += v;\n        }\n        return total + marked;\n    }\n}\n";
R["cx-m12-rising-run"] = "public class Solution {\n    // CONTRACT: the longest INCREASING RUN's length in arr.\n    // {3, 1, 2, 3, 0, 5} -> 3 (the 1,2,3 stretch).\n    // Empty -> 0, single element -> 1.\n    public static int longestRisingRun(int[] arr) {\n        if (arr.length == 0) { return 0; }\n        int best = 1;\n        int current = 1;\n        for (int i = 1; i < arr.length; i++) {\n            if (arr[i] > arr[i - 1]) {\n                current++;\n                if (current > best) { best = current; }\n            } else {\n                current = 1;\n            }\n        }\n        return best;\n    }\n}\n";
W["cx-m12-rising-run"] = "public class Solution {\n    // CONTRACT: the longest INCREASING RUN's length in arr.\n    // {3, 1, 2, 3, 0, 5} -> 3 (the 1,2,3 stretch).\n    // Empty -> 0, single element -> 1.\n    public static int longestRisingRun(int[] arr) {\n        if (arr.length == 0) { return 0; }\n        int best = 1;\n        int current = 1;\n        for (int i = 1; i < arr.length; i++) {\n            if (arr[i] >= arr[i - 1]) {\n                current++;\n                if (current > best) { best = current; }\n            } else {\n                current = 1;\n            }\n        }\n        return best;\n    }\n}\n";
R["cx-m12-best-price"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Sale {\n        private String item;\n        private int cents;\n        public Sale(String item, int cents) { this.item = item; this.cents = cents; }\n        public String getItem() { return item; }\n        public int getCents() { return cents; }\n    }\n\n    // CONTRACT: among sales of item, return the SMALLEST cents as a\n    // double; -1.0 when the item never appears.\n    public static double bestPrice(ArrayList<Sale> sales, String item) {\n        double best = -1.0;\n        for (Sale s : sales) {\n            if (s.getItem().equals(item)) {\n                if (best < 0 || s.getCents() < best) {\n                    best = s.getCents();\n                }\n            }\n        }\n        return best;\n    }\n}\n";
