R["cx-m14-sum-range"] = "public class Solution {\n    // FRQ-style Q1: implement from the spec below.\n    // (a) int sumRange(int lo, int hi): the sum lo + (lo+1) + ... + hi.\n    //     Precondition: 0 <= lo <= hi.\n    // (b) int sumEvenRange(int lo, int hi): the sum of the EVEN numbers\n    //     in [lo, hi]. Precondition: 0 <= lo <= hi. Use sumRange-style\n    //     logic; no helper required.\n    public static int sumRange(int lo, int hi) {\n        int total = 0;\n        for (int i = lo; i <= hi; i++) {\n            total += i;\n        }\n        return total;\n    }\n\n    public static int sumEvenRange(int lo, int hi) {\n        int total = 0;\n        for (int i = lo; i <= hi; i++) {\n            if (i % 2 == 0) {\n                total += i;\n            }\n        }\n        return total;\n    }\n}\n";
W["cx-m14-sum-range"] = "public class Solution {\n    // FRQ-style Q1: implement from the spec below.\n    // (a) int sumRange(int lo, int hi): the sum lo + (lo+1) + ... + hi.\n    //     Precondition: 0 <= lo <= hi.\n    // (b) int sumEvenRange(int lo, int hi): the sum of the EVEN numbers\n    //     in [lo, hi]. Precondition: 0 <= lo <= hi. Use sumRange-style\n    //     logic; no helper required.\n    public static int sumRange(int lo, int hi) {\n        int total = 0;\n        for (int i = lo; i <= hi; i++) {\n            total += i;\n        }\n        return total;\n    }\n\n    public static int sumEvenRange(int lo, int hi) {\n        int total = 0;\n        for (int i = lo; i <= hi; i++) {\n            if (i % 2 == 1) {\n                total += i;\n            }\n        }\n        return total;\n    }\n}\n";
R["cx-m14-tokens"] = "public class Solution {\n    // FRQ-style Q1b: token processing.\n    // (a) boolean isBalanced(String s): s contains only '(' and ')';\n    //     true when every prefix has at least as many '(' as ')' and\n    //     the total counts are equal. \"\" is balanced.\n    // (b) int depth(String s): the MAXIMUM nesting depth of the same\n    //     string; \"\" has depth 0. (Assume isBalanced(s) is true.)\n    public static boolean isBalanced(String s) {\n        int open = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == '(') {\n                open++;\n            } else {\n                open--;\n            }\n            if (open < 0) {\n                return false;\n            }\n        }\n        return open == 0;\n    }\n\n    public static int depth(String s) {\n        int level = 0;\n        int max = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == '(') {\n                level++;\n                if (level > max) {\n                    max = level;\n                }\n            } else {\n                level--;\n            }\n        }\n        return max;\n    }\n}\n";
W["cx-m14-tokens"] = "public class Solution {\n    // FRQ-style Q1b: token processing.\n    // (a) boolean isBalanced(String s): s contains only '(' and ')';\n    //     true when every prefix has at least as many '(' as ')' and\n    //     the total counts are equal. \"\" is balanced.\n    // (b) int depth(String s): the MAXIMUM nesting depth of the same\n    //     string; \"\" has depth 0. (Assume isBalanced(s) is true.)\n    public static boolean isBalanced(String s) {\n        int open = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == '(') {\n                open++;\n            } else {\n                open--;\n            }\n            if (open < 0) {\n                return true;\n            }\n        }\n        return open == 0;\n    }\n\n    public static int depth(String s) {\n        int level = 0;\n        int max = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == '(') {\n                level++;\n                if (level > max) {\n                    max = level;\n                }\n            } else {\n                level--;\n            }\n        }\n        return level;\n    }\n}\n";
R["cx-m14-count-char"] = "public class Solution {\n    // FRQ-style Q1, two-method shape:\n    // (a) int countChar(String s, char c): occurrences of c in s.\n    // (b) boolean scattered(String s, char c, int k): true when c\n    //     appears at least k times, using countChar.\n    //     Precondition: k >= 0.\n    public static int countChar(String s, char c) {\n        int count = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == c) {\n                count++;\n            }\n        }\n        return count;\n    }\n\n    public static boolean scattered(String s, char c, int k) {\n        return countChar(s, c) >= k;\n    }\n}\n";
W["cx-m14-count-char"] = "public class Solution {\n    // FRQ-style Q1, two-method shape:\n    // (a) int countChar(String s, char c): occurrences of c in s.\n    // (b) boolean scattered(String s, char c, int k): true when c\n    //     appears at least k times, using countChar.\n    //     Precondition: k >= 0.\n    public static int countChar(String s, char c) {\n        int count = 0;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) == c) {\n                count++;\n            }\n        }\n        return count;\n    }\n\n    public static boolean scattered(String s, char c, int k) {\n        return countChar(s, c) > k;\n    }\n}\n";
R["cx-cp-m14-word-metrics"] = "public class Solution {\n    public static int countWords(String s) {\n        int count = 0;\n        boolean inWord = false;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                if (!inWord) {\n                    count++;\n                }\n                inWord = true;\n            } else {\n                inWord = false;\n            }\n        }\n        return count;\n    }\n\n    public static String longestWord(String s) {\n        String best = \"\";\n        String current = \"\";\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                current += s.charAt(i);\n            } else {\n                if (current.length() > best.length()) {\n                    best = current;\n                }\n                current = \"\";\n            }\n        }\n        if (current.length() > best.length()) {\n            best = current;\n        }\n        return best;\n    }\n}\n";
W["cx-cp-m14-word-metrics"] = "public class Solution {\n    public static int countWords(String s) {\n        int count = 0;\n        boolean inWord = false;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                if (!inWord) {\n                    count++;\n                }\n                inWord = true;\n            } else {\n                inWord = false;\n            }\n        }\n        return count;\n    }\n\n    public static String longestWord(String s) {\n        String best = \"\";\n        String current = \"\";\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                current += s.charAt(i);\n            } else {\n                if (current.length() > best.length()) {\n                    best = current;\n                }\n                current = \"\";\n            }\n        }\n        return best;\n    }\n}\n";
R["cx-m15-signaler"] = "public class Solution {\n    // SPEC TABLE (complete the class):\n    // private int level  \u2014 starts at 1\n    // private int streak \u2014 starts at 0\n    // Signaler()         \u2014 both at start values\n    // void boost()  \u2014 level += streak; THEN streak++\n    // void reset()  \u2014 level = 1; streak = 0\n    // int getLevel()\n    // int getStreak()\n    public static class Signaler {\n        private int level;\n        private int streak;\n\n        public Signaler() {\n            level = 1;\n            streak = 0;\n        }\n\n        public void boost() {\n            level += streak;\n            streak++;\n        }\n\n        public void reset() {\n            level = 1;\n            streak = 0;\n        }\n\n        public int getLevel() { return level; }\n        public int getStreak() { return streak; }\n    }\n}\n";
W["cx-m15-signaler"] = "public class Solution {\n    // SPEC TABLE (complete the class):\n    // private int level  \u2014 starts at 1\n    // private int streak \u2014 starts at 0\n    // Signaler()         \u2014 both at start values\n    // void boost()  \u2014 level += streak; THEN streak++\n    // void reset()  \u2014 level = 1; streak = 0\n    // int getLevel()\n    // int getStreak()\n    public static class Signaler {\n        private int level;\n        private int streak;\n\n        public Signaler() {\n            level = 1;\n            streak = 0;\n        }\n\n        public void boost() {\n            streak++;\n            level += streak;\n        }\n\n        public void reset() {\n            level = 1;\n            streak = 0;\n        }\n\n        public int getLevel() { return level; }\n        public int getStreak() { return streak; }\n    }\n}\n";
R["cx-m15-register"] = "public class Solution {\n    // SPEC: a cash register.\n    // private int itemCount \u2014 starts 0\n    // private int totalCents \u2014 starts 0\n    // void ring(int cents) \u2014 item count +1, total += cents\n    // void clear() \u2014 both to start values\n    // int getItemCount() / int getTotalCents()\n    // int average() \u2014 totalCents / itemCount as int division;\n    //   returns 0 when empty. (Precondition-safe: guard the empty case.)\n    public static class Register {\n        private int itemCount;\n        private int totalCents;\n\n        public Register() {\n            itemCount = 0;\n            totalCents = 0;\n        }\n\n        public void ring(int cents) {\n            itemCount++;\n            totalCents += cents;\n        }\n\n        public void clear() {\n            itemCount = 0;\n            totalCents = 0;\n        }\n\n        public int getItemCount() { return itemCount; }\n        public int getTotalCents() { return totalCents; }\n\n        public int average() {\n            if (itemCount == 0) {\n                return 0;\n            }\n            return totalCents / itemCount;\n        }\n    }\n}\n";
W["cx-m15-register"] = "public class Solution {\n    // SPEC: a cash register.\n    // private int itemCount \u2014 starts 0\n    // private int totalCents \u2014 starts 0\n    // void ring(int cents) \u2014 item count +1, total += cents\n    // void clear() \u2014 both to start values\n    // int getItemCount() / int getTotalCents()\n    // int average() \u2014 totalCents / itemCount as int division;\n    //   returns 0 when empty. (Precondition-safe: guard the empty case.)\n    public static class Register {\n        private int itemCount;\n        private int totalCents;\n\n        public Register() {\n            itemCount = 0;\n            totalCents = 0;\n        }\n\n        public void ring(int cents) {\n            itemCount++;\n            totalCents += cents;\n        }\n\n        public void clear() {\n            itemCount = 0;\n            totalCents = 0;\n        }\n\n        public int getItemCount() { return itemCount; }\n        public int getTotalCents() { return totalCents; }\n\n        public int average() {\n            if (itemCount == 0) {\n                return -1;\n            }\n            return totalCents / itemCount;\n        }\n    }\n}\n";
R["cx-m15-wordbag"] = "public class Solution {\n    // SPEC: a word accumulator.\n    // private String joined \u2014 starts \"\"\n    // private int wordCount \u2014 starts 0\n    // void absorb(WordBag other) \u2014 append other's joined (in order)\n    //   to THIS joined and add other's wordCount to THIS count;\n    //   other is NOT modified.\n    // void add(String w) \u2014 append w (space-separated) and count it\n    // String getJoined() / int getCount()\n    public static class WordBag {\n        private String joined;\n        private int wordCount;\n\n        public WordBag() {\n            joined = \"\";\n            wordCount = 0;\n        }\n\n        public void add(String w) {\n            if (wordCount > 0) {\n                joined += \" \";\n            }\n            joined += w;\n            wordCount++;\n        }\n\n        public void absorb(WordBag other) {\n            if (other.wordCount > 0) {\n                if (wordCount > 0) {\n                    joined += \" \";\n                }\n                joined += other.joined;\n                wordCount += other.wordCount;\n            }\n        }\n\n        public String getJoined() { return joined; }\n        public int getCount() { return wordCount; }\n    }\n}\n";
W["cx-m15-wordbag"] = "public class Solution {\n    // SPEC: a word accumulator.\n    // private String joined \u2014 starts \"\"\n    // private int wordCount \u2014 starts 0\n    // void absorb(WordBag other) \u2014 append other's joined (in order)\n    //   to THIS joined and add other's wordCount to THIS count;\n    //   other is NOT modified.\n    // void add(String w) \u2014 append w (space-separated) and count it\n    // String getJoined() / int getCount()\n    public static class WordBag {\n        private String joined;\n        private int wordCount;\n\n        public WordBag() {\n            joined = \"\";\n            wordCount = 0;\n        }\n\n        public void add(String w) {\n            if (wordCount > 0) {\n                joined += \" \";\n            }\n            joined += w;\n            wordCount++;\n        }\n\n        public void absorb(WordBag other) {\n            if (other.wordCount > 0) {\n                if (other.wordCount > 0) {\n                    other.joined += \" \";\n                }\n                other.joined += joined;\n                other.wordCount += wordCount;\n            }\n        }\n\n        public String getJoined() { return joined; }\n        public int getCount() { return wordCount; }\n    }\n}\n";
R["cx-m15-fix-downcounter"] = "public class Solution {\n    // Repair: this DownCounter almost matches its spec.\n    // SPEC: private int remaining (starts 5);\n    // boolean tick() \u2014 when remaining > 0: decrement and return true;\n    //   when remaining == 0: return false, NO change.\n    // int getRemaining().\n    // BUGS (find via the checklist): field never initialized to 5, and\n    // tick() counts below zero.\n    public static class DownCounter {\n        private int remaining;\n\n        public DownCounter() {\n            remaining = 5;\n        }\n\n        public boolean tick() {\n            if (remaining > 0) {\n                remaining--;\n                return true;\n            }\n            return false;\n        }\n\n        public int getRemaining() { return remaining; }\n    }\n}\n";
W["cx-m15-fix-downcounter"] = "public class Solution {\n    // Repair: this DownCounter almost matches its spec.\n    // SPEC: private int remaining (starts 5);\n    // boolean tick() \u2014 when remaining > 0: decrement and return true;\n    //   when remaining == 0: return false, NO change.\n    // int getRemaining().\n    // BUGS (find via the checklist): field never initialized to 5, and\n    // tick() counts below zero.\n    public static class DownCounter {\n        private int remaining;\n\n        public DownCounter() {\n            remaining = 5;\n        }\n\n        public boolean tick() {\n            if (remaining >= 0) {\n                remaining--;\n                return true;\n            }\n            return false;\n        }\n\n        public int getRemaining() { return remaining; }\n    }\n}\n";
R["cx-m15-grid-summary"] = "public class Solution {\n    // SPEC: a tiny grid summary class (Q2 with a helper):\n    // private int[][] grid; private int rows; private int cols;\n    // GridSummary(int[][] g) \u2014 store g, rows = g.length, cols = g[0].length\n    // private int colSum(int c) \u2014 sum of column c (helper)\n    // public int maxColSum() \u2014 the largest colSum (uses the helper)\n    public static class GridSummary {\n        private int[][] grid;\n        private int rows;\n        private int cols;\n\n        public GridSummary(int[][] g) {\n            grid = g;\n            rows = g.length;\n            cols = g[0].length;\n        }\n\n        private int colSum(int c) {\n            int sum = 0;\n            for (int r = 0; r < rows; r++) {\n                sum += grid[r][c];\n            }\n            return sum;\n        }\n\n        public int maxColSum() {\n            int best = colSum(0);\n            for (int c = 1; c < cols; c++) {\n                if (colSum(c) > best) {\n                    best = colSum(c);\n                }\n            }\n            return best;\n        }\n    }\n}\n";
W["cx-m15-grid-summary"] = "public class Solution {\n    // SPEC: a tiny grid summary class (Q2 with a helper):\n    // private int[][] grid; private int rows; private int cols;\n    // GridSummary(int[][] g) \u2014 store g, rows = g.length, cols = g[0].length\n    // private int colSum(int c) \u2014 sum of column c (helper)\n    // public int maxColSum() \u2014 the largest colSum (uses the helper)\n    public static class GridSummary {\n        private int[][] grid;\n        private int rows;\n        private int cols;\n\n        public GridSummary(int[][] g) {\n            grid = g;\n            rows = g.length;\n            cols = g[0].length;\n        }\n\n        private int colSum(int c) {\n            int sum = 0;\n            for (int r = 0; r < rows; r++) {\n                sum += grid[r][c];\n            }\n            return sum;\n        }\n\n        public int maxColSum() {\n            int best = colSum(0);\n            for (int c = 1; c < cols; c++) {\n                if (colSum(c) < best) {\n                    best = colSum(c);\n                }\n            }\n            return best;\n        }\n    }\n}\n";
