R["cx-m16-customer-total"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Order {\n        private String customer;\n        private int cents;\n        public Order(String customer, int cents) {\n            this.customer = customer;\n            this.cents = cents;\n        }\n        public String getCustomer() { return customer; }\n        public int getCents() { return cents; }\n    }\n\n    // CONTRACT: total cents across all orders of `name`.\n    public static int customerTotal(ArrayList<Order> orders, String name) {\n        int total = 0;\n        for (Order o : orders) {\n            if (o.getCustomer().equals(name)) {\n                total += o.getCents();\n            }\n        }\n        return total;\n    }\n}\n";
