W["cx-m16-first-above"] = "import java.util.ArrayList;\n\npublic class Solution {\n    // CONTRACT: index of the FIRST Integer strictly greater than\n    // `threshold`, or -1 when none. Use indexOf-style logic.\n    public static int firstAbove(ArrayList<Integer> nums, int threshold) {\n        for (int i = 0; i < nums.size(); i++) {\n            if (nums.get(i) > threshold) {\n                return nums.size() - 1 - i;\n            }\n        }\n        return -1;\n    }\n}\n";
R["cx-cp-m16-zone-tickets"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Ticket {\n        private String zone;\n        private int minutes;\n        public Ticket(String zone, int minutes) {\n            this.zone = zone;\n            this.minutes = minutes;\n        }\n        public String getZone() { return zone; }\n        public int getMinutes() { return minutes; }\n    }\n\n    // TWO-PART Q3:\n    // (a) int zoneTotal(ArrayList<Ticket> tickets, String zone):\n    //     total minutes of tickets in `zone`.\n    // (b) boolean overtime(ArrayList<Ticket> tickets, String zone,\n    //     int limit): true when zoneTotal(...) for that zone is\n    //     strictly greater than limit. Use part (a).\n    public static int zoneTotal(ArrayList<Ticket> tickets, String zone) {\n        int total = 0;\n        for (Ticket t : tickets) {\n            if (t.getZone().equals(zone)) {\n                total += t.getMinutes();\n            }\n        }\n        return total;\n    }\n\n    public static boolean overtime(ArrayList<Ticket> tickets, String zone, int limit) {\n        return zoneTotal(tickets, zone) > limit;\n    }\n}\n";
W["cx-cp-m16-zone-tickets"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Ticket {\n        private String zone;\n        private int minutes;\n        public Ticket(String zone, int minutes) {\n            this.zone = zone;\n            this.minutes = minutes;\n        }\n        public String getZone() { return zone; }\n        public int getMinutes() { return minutes; }\n    }\n\n    // TWO-PART Q3:\n    // (a) int zoneTotal(ArrayList<Ticket> tickets, String zone):\n    //     total minutes of tickets in `zone`.\n    // (b) boolean overtime(ArrayList<Ticket> tickets, String zone,\n    //     int limit): true when zoneTotal(...) for that zone is\n    //     strictly greater than limit. Use part (a).\n    public static int zoneTotal(ArrayList<Ticket> tickets, String zone) {\n        int total = 0;\n        for (Ticket t : tickets) {\n            if (t.getZone().equals(zone)) {\n                total += t.getMinutes();\n            }\n        }\n        return total;\n    }\n\n    public static boolean overtime(ArrayList<Ticket> tickets, String zone, int limit) {\n        return zoneTotal(tickets, zone) >= limit;\n    }\n}\n";
R["cx-m17-find-max-pos"] = "public class Solution {\n    // CONTRACT: {row, col} of the LARGEST value (earliest tie, row-major\n    // order). Precondition: grid.length >= 1, rectangular.\n    public static int[] findMax(int[][] grid) {\n        int[] at = new int[2];\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                if (grid[r][c] > grid[at[0]][at[1]]) {\n                    at[0] = r;\n                    at[1] = c;\n                }\n            }\n        }\n        return at;\n    }\n}\n";
W["cx-m17-find-max-pos"] = "public class Solution {\n    // CONTRACT: {row, col} of the LARGEST value (earliest tie, row-major\n    // order). Precondition: grid.length >= 1, rectangular.\n    public static int[] findMax(int[][] grid) {\n        int[] at = new int[2];\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                if (grid[r][c] >= grid[at[0]][at[1]]) {\n                    at[0] = r;\n                    at[1] = c;\n                }\n            }\n        }\n        return at;\n    }\n}\n";
