R["cx-cp-m18-second-max"] = "public class Solution {\n    public static int secondMax(int[] arr) {\n        int max = Integer.MIN_VALUE;\n        int second = Integer.MIN_VALUE;\n        boolean hasSecond = false;\n        for (int i = 0; i < arr.length; i++) {\n            if (arr[i] > max) {\n                second = max;\n                hasSecond = hasSecond || max != Integer.MIN_VALUE;\n                max = arr[i];\n            } else if (arr[i] < max && arr[i] > second) {\n                second = arr[i];\n                hasSecond = true;\n            }\n        }\n        if (!hasSecond) {\n            return -1;\n        }\n        return second;\n    }\n}\n";
W["cx-cp-m18-second-max"] = "public class Solution {\n    public static int secondMax(int[] arr) {\n        int max = Integer.MIN_VALUE;\n        int second = Integer.MIN_VALUE;\n        boolean hasSecond = false;\n        for (int i = 0; i < arr.length; i++) {\n            if (arr[i] > max) {\n                second = max;\n                hasSecond = hasSecond || max != Integer.MIN_VALUE;\n                max = arr[i];\n            } else if (arr[i] <= max && arr[i] > second) {\n                second = arr[i];\n                hasSecond = true;\n            }\n        }\n        if (!hasSecond) {\n            return -1;\n        }\n        return second;\n    }\n}\n";
R["cx-m19-differ"] = "public class Solution {\n    // UNLABELED. Return the number of positions where the two arrays\n    // differ; treat the extra tail of the longer array as differing.\n    // differ({1, 2, 3}, {1, 5}) == 2\n    public static int differ(int[] a, int[] b) {\n        int n = Math.min(a.length, b.length);\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            if (a[i] != b[i]) {\n                count++;\n            }\n        }\n        return count + Math.abs(a.length - b.length);\n    }\n}\n";
