R["cx-m19-limiter"] = "public class Solution {\n    // UNLABELED. Complete the class per its table:\n    // private int count (starts 0); private boolean stuck (starts false)\n    // void bump() \u2014 when NOT stuck: count++; when count reaches 3,\n    //   set stuck = true\n    // void unstick() \u2014 stuck = false (count unchanged)\n    // int getCount() / boolean isStuck()\n    public static class Limiter {\n        private int count;\n        private boolean stuck;\n\n        public Limiter() {\n            count = 0;\n            stuck = false;\n        }\n\n        public void bump() {\n            if (!stuck) {\n                count++;\n                if (count >= 3) {\n                    stuck = true;\n                }\n            }\n        }\n\n        public void unstick() {\n            stuck = false;\n        }\n\n        public int getCount() { return count; }\n        public boolean isStuck() { return stuck; }\n    }\n}\n";
W["cx-m19-limiter"] = "public class Solution {\n    // UNLABELED. Complete the class per its table:\n    // private int count (starts 0); private boolean stuck (starts false)\n    // void bump() \u2014 when NOT stuck: count++; when count reaches 3,\n    //   set stuck = true\n    // void unstick() \u2014 stuck = false (count unchanged)\n    // int getCount() / boolean isStuck()\n    public static class Limiter {\n        private int count;\n        private boolean stuck;\n\n        public Limiter() {\n            count = 0;\n            stuck = false;\n        }\n\n        public void bump() {\n            if (!stuck) {\n                count++;\n                if (count > 3) {\n                    stuck = true;\n                }\n            }\n        }\n\n        public void unstick() {\n            stuck = false;\n        }\n\n        public int getCount() { return count; }\n        public boolean isStuck() { return stuck; }\n    }\n}\n";
R["cx-m19-odd-one"] = "public class Solution {\n    // UNLABELED. Return the element of arr that appears an ODD number\n    // of times (the test guarantees exactly one such value).\n    public static int oddOne(int[] arr) {\n        for (int i = 0; i < arr.length; i++) {\n            int count = 0;\n            for (int j = 0; j < arr.length; j++) {\n                if (arr[j] == arr[i]) {\n                    count++;\n                }\n            }\n            if (count % 2 == 1) {\n                return arr[i];\n            }\n        }\n        return 0;\n    }\n}\n";
