W["cx-cp-m19-cumulative"] = "public class Solution {\n    public static String longestStarting(String[] words, char letter) {\n        String best = \"\";\n        for (String w : words) {\n            if (w.length() > 0 && w.charAt(w.length() - 1) == letter) {\n                if (w.length() > best.length()) {\n                    best = w;\n                }\n            }\n        }\n        return best;\n    }\n}\n";
R["cx-m20-sim-q1"] = "public class Solution {\n    // SIMULATED Q1 \u2014 Methods and Control Structures (22 minutes).\n    // Part (a): int digitSum(int n) \u2014 sum of the decimal digits of\n    //   n (n >= 0). 0 -> 0.\n    // Part (b): boolean divisibleBy3(int n) \u2014 true when digitSum(n)\n    //   is divisible by 3. Use part (a).\n    public static int digitSum(int n) {\n        int sum = 0;\n        while (n > 0) {\n            sum += n % 10;\n            n /= 10;\n        }\n        return sum;\n    }\n\n    public static boolean divisibleBy3(int n) {\n        return digitSum(n) % 3 == 0;\n    }\n}\n";
W["cx-m20-sim-q1"] = "public class Solution {\n    // SIMULATED Q1 \u2014 Methods and Control Structures (22 minutes).\n    // Part (a): int digitSum(int n) \u2014 sum of the decimal digits of\n    //   n (n >= 0). 0 -> 0.\n    // Part (b): boolean divisibleBy3(int n) \u2014 true when digitSum(n)\n    //   is divisible by 3. Use part (a).\n    public static int digitSum(int n) {\n        int sum = 0;\n        while (n > 0) {\n            sum += n % 10;\n            n /= 10;\n        }\n        return sum;\n    }\n\n    public static boolean divisibleBy3(int n) {\n        return digitSum(n) % 3 == 1;\n    }\n}\n";
R["cx-m20-sim-q3"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Car {\n        private String color;\n        private int miles;\n        public Car(String color, int miles) {\n            this.color = color;\n            this.miles = miles;\n        }\n        public String getColor() { return color; }\n        public int getMiles() { return miles; }\n    }\n\n    // SIMULATED Q3 \u2014 ArrayList analysis (22 minutes).\n    // Part (a): int fleetMiles(ArrayList<Car> cars, String color) \u2014\n    //   total miles of cars of that color (0 when none).\n    // Part (b): int removeColor(ArrayList<Car> cars, String color) \u2014\n    //   remove ALL cars of that color in place and return how many\n    //   were removed.\n    public static int fleetMiles(ArrayList<Car> cars, String color) {\n        int total = 0;\n        for (Car c : cars) {\n            if (c.getColor().equals(color)) {\n                total += c.getMiles();\n            }\n        }\n        return total;\n    }\n\n    public static int removeColor(ArrayList<Car> cars, String color) {\n        int removed = 0;\n        for (int i = cars.size() - 1; i >= 0; i--) {\n            if (cars.get(i).getColor().equals(color)) {\n                cars.remove(i);\n                removed++;\n            }\n        }\n        return removed;\n    }\n}\n";
W["cx-m20-sim-q3"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Car {\n        private String color;\n        private int miles;\n        public Car(String color, int miles) {\n            this.color = color;\n            this.miles = miles;\n        }\n        public String getColor() { return color; }\n        public int getMiles() { return miles; }\n    }\n\n    // SIMULATED Q3 \u2014 ArrayList analysis (22 minutes).\n    // Part (a): int fleetMiles(ArrayList<Car> cars, String color) \u2014\n    //   total miles of cars of that color (0 when none).\n    // Part (b): int removeColor(ArrayList<Car> cars, String color) \u2014\n    //   remove ALL cars of that color in place and return how many\n    //   were removed.\n    public static int fleetMiles(ArrayList<Car> cars, String color) {\n        int total = 0;\n        for (Car c : cars) {\n            if (c.getColor().equals(color)) {\n                total += c.getMiles();\n            }\n        }\n        return total;\n    }\n\n    public static int removeColor(ArrayList<Car> cars, String color) {\n        int removed = 0;\n        for (int i = 0; i < cars.size(); i++) {\n            if (cars.get(i).getColor().equals(color)) {\n                cars.remove(i);\n                removed++;\n            }\n        }\n        return removed;\n    }\n}\n";
R["cx-m20-sim-q4"] = "public class Solution {\n    // SIMULATED Q4 \u2014 2D array (22 minutes). Rectangular grid,\n    // grid.length >= 1.\n    // Part (a): int countAbove(int[][] grid, int threshold) \u2014 cells\n    //   strictly greater than threshold.\n    // Part (b): int[] colBelowAvg(int[][] grid) \u2014 for each column,\n    //   1 when its sum is >= the grid's TOTAL average, else 0.\n    //   (Average as a double; compare column SUM against it.)\n    public static int countAbove(int[][] grid, int threshold) {\n        int count = 0;\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                if (grid[r][c] > threshold) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n\n    public static int[] colBelowAvg(int[][] grid) {\n        int total = 0;\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                total += grid[r][c];\n            }\n        }\n        double avg = (double) total / (grid.length * grid[0].length);\n        int[] verdict = new int[grid[0].length];\n        for (int c = 0; c < grid[0].length; c++) {\n            int colSum = 0;\n            for (int r = 0; r < grid.length; r++) {\n                colSum += grid[r][c];\n            }\n            verdict[c] = (colSum >= avg) ? 1 : 0;\n        }\n        return verdict;\n    }\n}\n";
W["cx-m20-sim-q4"] = "public class Solution {\n    // SIMULATED Q4 \u2014 2D array (22 minutes). Rectangular grid,\n    // grid.length >= 1.\n    // Part (a): int countAbove(int[][] grid, int threshold) \u2014 cells\n    //   strictly greater than threshold.\n    // Part (b): int[] colBelowAvg(int[][] grid) \u2014 for each column,\n    //   1 when its sum is >= the grid's TOTAL average, else 0.\n    //   (Average as a double; compare column SUM against it.)\n    public static int countAbove(int[][] grid, int threshold) {\n        int count = 0;\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                if (grid[r][c] > threshold) {\n                    count++;\n                }\n            }\n        }\n        return count;\n    }\n\n    public static int[] colBelowAvg(int[][] grid) {\n        int total = 0;\n        for (int r = 0; r < grid.length; r++) {\n            for (int c = 0; c < grid[r].length; c++) {\n                total += grid[r][c];\n            }\n        }\n        double avg = (double) total / (grid.length * grid[0].length);\n        int[] verdict = new int[grid[0].length];\n        for (int c = 0; c < grid[0].length; c++) {\n            int colSum = 0;\n            for (int r = 0; r < grid.length; r++) {\n                colSum += grid[r][c];\n            }\n            verdict[c] = (colSum > avg) ? 1 : 0;\n        }\n        return verdict;\n    }\n}\n";
R["cx-m20-sim-mixed"] = "public class Solution {\n    // SIMULATED MCQ-STYLE TRACE (the 42-question section compressed).\n    // Predict WITHOUT running, then reproduce exactly:\n    //   m({4, 9, 2}) -> ?   trace: evens halved in place, odds doubled+1,\n    //   return sum of final values minus count of changed cells.\n    public static int m(int[] nums) {\n        int changed = 0;\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] % 2 == 0) {\n                nums[i] = nums[i] / 2;\n                changed++;\n            } else {\n                nums[i] = nums[i] * 2 + 1;\n            }\n        }\n        int total = 0;\n        for (int v : nums) {\n            total += v;\n        }\n        return total - changed;\n    }\n}\n";
W["cx-m20-sim-mixed"] = "public class Solution {\n    // SIMULATED MCQ-STYLE TRACE (the 42-question section compressed).\n    // Predict WITHOUT running, then reproduce exactly:\n    //   m({4, 9, 2}) -> ?   trace: evens halved in place, odds doubled+1,\n    //   return sum of final values minus count of changed cells.\n    public static int m(int[] nums) {\n        int changed = 0;\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] % 2 == 0) {\n                nums[i] = nums[i] / 2;\n                changed++;\n            } else {\n                nums[i] = nums[i] * 2 + 1;\n            }\n        }\n        int total = 0;\n        for (int v : nums) {\n            total += v;\n        }\n        return total + changed;\n    }\n}\n";
R["cx-m14-word-metrics-practice"] = "public class Solution {\n    public static int countWords(String s) {\n        int count = 0;\n        boolean inWord = false;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                if (!inWord) {\n                    count++;\n                }\n                inWord = true;\n            } else {\n                inWord = false;\n            }\n        }\n        return count;\n    }\n\n    public static String longestWord(String s) {\n        String best = \"\";\n        String current = \"\";\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                current += s.charAt(i);\n            } else {\n                if (current.length() > best.length()) {\n                    best = current;\n                }\n                current = \"\";\n            }\n        }\n        if (current.length() > best.length()) {\n            best = current;\n        }\n        return best;\n    }\n}\n";
W["cx-m14-word-metrics-practice"] = "public class Solution {\n    public static int countWords(String s) {\n        int count = 0;\n        boolean inWord = false;\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                if (!inWord) {\n                    count++;\n                }\n                inWord = true;\n            } else {\n                inWord = false;\n            }\n        }\n        return count;\n    }\n\n    public static String longestWord(String s) {\n        String best = \"\";\n        String current = \"\";\n        for (int i = 0; i < s.length(); i++) {\n            if (s.charAt(i) != ' ') {\n                current += s.charAt(i);\n            } else {\n                if (current.length() > best.length()) {\n                    best = current;\n                }\n                current = \"\";\n            }\n        }\n        return best;\n    }\n}\n";
R["cx-m20-fleet-practice"] = "import java.util.ArrayList;\n\npublic class Solution {\n    public static class Car {\n        private String color;\n        private int miles;\n        public Car(String color, int miles) {\n            this.color = color;\n            this.miles = miles;\n        }\n        public String getColor() { return color; }\n        public int getMiles() { return miles; }\n    }\n\n    // SIMULATED Q3 \u2014 ArrayList analysis (22 minutes).\n    // Part (a): int fleetMiles(ArrayList<Car> cars, String color) \u2014\n    //   total miles of cars of that color (0 when none).\n    // Part (b): int removeColor(ArrayList<Car> cars, String color) \u2014\n    //   remove ALL cars of that color in place and return how many\n    //   were removed.\n    public static int fleetMiles(ArrayList<Car> cars, String color) {\n        int total = 0;\n        for (Car c : cars) {\n            if (c.getColor().equals(color)) {\n                total += c.getMiles();\n            }\n        }\n        return total;\n    }\n\n    public static int removeColor(ArrayList<Car> cars, String color) {\n        int removed = 0;\n        for (int i = cars.size() - 1; i >= 0; i--) {\n            if (cars.get(i).getColor().equals(color)) {\n                cars.remove(i);\n                removed++;\n            }\n        }\n        return removed;\n    }\n}\n";
